import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import api from "../api/axios";

export default function RestaurantList() {
  const [restaurants, setRestaurants] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.get("/restaurants").then(({ data }) => {
      setRestaurants(data);
      setLoading(false);
    });
  }, []);

  return (
    <div className="page">
      <div className="eyebrow">Order food</div>
      <h1>Restaurants near you</h1>
      <hr className="route-rule" style={{ margin: "20px 0 28px" }} />

      {loading && <p style={{ color: "var(--paper-dim)" }}>Loading restaurants…</p>}
      {!loading && restaurants.length === 0 && (
        <div className="empty-state">No restaurants are open right now. Check back soon.</div>
      )}

      <div className="grid">
        {restaurants.map((r) => (
          <Link key={r._id} to={`/restaurants/${r._id}`} className="card" style={{ textDecoration: "none" }}>
            <h3>{r.name}</h3>
            <p style={{ color: "var(--paper-dim)", fontSize: 14, margin: "6px 0 12px" }}>
              {r.cuisine || "Multi-cuisine"}
            </p>
            <span className="badge badge-live">Open now</span>
          </Link>
        ))}
      </div>
    </div>
  );
}
